// Design calculator only. Does not import or change game/runtime configuration.
// node docs/balance/stat-scaling-model.cjs --write  (regenerate tables + CSV)
// node docs/balance/stat-scaling-model.cjs --check  (validate math + generated files)
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const rarities = [
  ['Common',20,.05,'#B0B0B0'], ['Uncommon',60,.075,'#4BB543'],
  ['Rare',180,.10,'#2980B9'], ['Superior',540,.13,'#8E44AD'],
  ['Exalted',1400,.165,'#D35400'], ['Legendary',3500,.20,'#F1C40F'],
  ['Mythical',7000,.30,'#E74C3C'], ['Transcendent',10000,.35,'#1ABC9C'],
  ['Ascendant',14000,.40,'#E056FD'], ['Ethereal',20000,.45,'#686DE0'],
  ['Immortal',28000,.50,'#FF7979'], ['Divine',40000,.55,'#F9CA24'],
  ['Celestial',56000,.60,'#00D2D3'], ['Primordial',80000,.65,'#FF3838'],
  ['Supreme',112000,.70,'#BADC58'], ['Origin',160000,.75,'#FF9FF3'],
];
const benchmarkRarityCount = 7; // Mythical reference quality for hero level 50 / floor 50; no acquisition rule.
const weaponStars = [1,1.6,2.5,4,6.5,10,16];
const heroes = [
  {id:'hero_han',name:'Han',stars:1,atk:40,hp:300,interval:.85,range:6,labor:14,role:'Striker',facility:'None'},
  {id:'hero_jenna',name:'Jenna',stars:1,atk:34,hp:210,interval:.8,range:28,labor:13,role:'Marksman',facility:'None'},
  {id:'hero_catio',name:'Catio',stars:1,atk:24,hp:280,interval:1.05,range:6,labor:20,role:'Miner',facility:'None'},
  {id:'hero_aaron',name:'Aaron',stars:2,atk:28,hp:450,interval:1.1,range:7,labor:16,role:'Vanguard',facility:'Infirmary'},
  {id:'hero_velkist',name:'Velkist',stars:2,atk:44,hp:300,interval:.75,range:6,labor:14,role:'Striker',facility:'None'},
  {id:'hero_eolka',name:'Eolka',stars:3,atk:52,hp:230,interval:1,range:30,labor:22,role:'Scholar',facility:'None'},
  {id:'hero_archon',name:'Sovereign Archon',stars:3,atk:65,hp:350,interval:.8,range:14,labor:25,role:'Striker',facility:'All (+25% once)'},
];
for (const hero of heroes) hero.moveSpeed = 20; // Current simulation's launch baseline, studs/s.
// [floor, hero stars, hero level, inherent weapon rarity, progressive weapon stars]
// Expected earned builds BEFORE the encounter; never rewards or automatic stats.
const builds = [
  [1,1,1,1,1], [5,1,5,1,2], [10,1,10,2,2],
  [15,2,15,2,3], [20,2,20,3,3], [25,3,25,3,4],
  [30,3,30,4,5], [35,4,35,5,5], [40,4,40,6,6],
  [45,5,45,6,6], [50,5,50,7,7],
];
const growth = (s,l) => 3**(s-1) * 1.08**(l-1);
const labor = (h,s,l,q=1,synergy=false) => h.labor*q*1.35**(s-1)*(1+.05*(l-1))*(synergy?1.25:1);
const power = (r,w) => rarities[r-1][1]*weaponStars[w-1];
function stats(h,s,l,r,w,q=1,overdrive=false) {
  const g = growth(s,l);
  const p = r ? power(r,w) : 0;
  const speed = r ? rarities[r-1][2] : 0;
  const atk = Math.round(h.atk*q*g*(1+p/40));
  const hp = Math.round(h.hp*q*g);
  const interval = Math.max(.2,h.interval/((1+speed)*(overdrive?1.4:1)));
  // Current cooldown reset discards the remaining fraction of a simulation tick.
  const tickInterval = Math.ceil(interval/.2 - 1e-10)*.2;
  return {atk,hp,moveSpeed:h.moveSpeed,attackSpeed:1/interval,interval,tickInterval,dps:atk/tickInterval,continuousDps:atk/interval};
}
const anchors = builds.map(([floor,s,l,r,w]) => {
  const hero = stats(heroes[0],s,l,r,w);
  return {floor,s,l,r,w,hero,dps:5*hero.dps};
});
function interpolate(f,field) {
  const right = anchors.find(a=>a.floor>=f);
  const left = [...anchors].reverse().find(a=>a.floor<=f);
  const val = a => field==='dps' ? a.dps : a.hero.hp;
  if (right===left) return val(left);
  const t = (f-left.floor)/(right.floor-left.floor);
  return val(left)*(val(right)/val(left))**t;
}
function floorStats(f) {
  const dps = interpolate(f,'dps'), hp = interpolate(f,'hp');
  return {floor:f,dps,hp,regularHP:Math.round(2*dps),eliteHP:Math.round(8*dps),
    bossHP:Math.round(45*dps),regularATK:Math.round(.015*hp),eliteATK:Math.round(.03*hp),
    bossATK:Math.round(.04*hp)};
}
const n = (v,d=0) => v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const table = (heads,rows) => [
  '| '+heads.join(' | ')+' |', '| '+heads.map(()=>'---').join(' | ')+' |',
  ...rows.map(row=>'| '+row.join(' | ')+' |'),
].join('\n');

function outputs() {
  const f50 = floorStats(50);
  const mixed = heroes.filter(h=>['Han','Jenna','Aaron','Velkist','Eolka'].includes(h.name));
  let md = `# Generated stat scaling reference\n\nStatus: proposed design, 2026-10-22; no runtime changes or Studio playtest claim.\n\nGenerated by [stat-scaling-model.cjs](stat-scaling-model.cjs). Run from the repository root with Node and \`--write\` to regenerate, or \`--check\` to verify. The [50-floor CSV](FLOOR_SCALING.csv) contains the complete enemy curve.\n\n## Calculation contract\n\n- Quality \`q = 1.00\`; rested heroes; no critical hits, Overdrive, exposure, or other damage bonus.\n- Hero growth \`G = 3^(S-1) * 1.08^(L-1)\`; promotion keeps level.\n- Weapon power \`P = InherentRarityPower * WeaponStarMultiplier\`.\n- \`AttackDamage = round(SeedDamage * q * G * (1 + P/40))\`; \`HP = round(SeedHP * q * G)\`.\n- Weapon speed comes from rarity only. \`Interval = max(0.20, BaseInterval / ((1 + SpeedBonus) * OverdriveMult))\`.\n- The conservative 5 Hz model uses \`TickInterval = 0.20 * ceil(Interval/0.20)\`, with a tiny numerical tolerance at exact tick boundaries. \`DPS = AttackDamage/TickInterval\`.\n- Hero combat stats are movement speed, attack speed, attack damage, and health. Base movement speed is 20 studs/s for every launch hero; it does not receive exponential scaling. Range is targeting metadata; labor is facility output.\n- Five copies of Han are the reproducible calibration squad. A mixed squad is checked separately. These are earned builds, not automatic bonuses from entering a floor.\n- Interpolate the two bracketing checkpoint DPS values geometrically for every intermediate floor; interpolate reference HP the same way. Enemy health is \`round(DPS * [2, 8, 45])\` for regular/elite/boss; basic ATK is \`round(ReferenceHP * [0.015, 0.030, 0.040])\`. Only milestone floors spawn bosses.\n\n## Expected builds and squad output\n\n`;
  md += table(['Floor','Hero stars','Level','Weapon rarity','Weapon stars','Han attack damage / hit','Han health','Tick interval (s)','Squad DPS','75% uptime DPS'],anchors.map(a=>[
    a.floor,a.s,a.l,rarities[a.r-1][0],a.w,n(a.hero.atk),n(a.hero.hp),n(a.hero.tickInterval,2),n(a.dps),n(.75*a.dps),
  ]));
  md += '\n\n## Enemy durability and basic attack checkpoints\n\n';
  md += table(['Floor','Regular HP','Elite HP','Boss HP','Regular damage','Elite damage','Boss damage'],anchors.map(a=>{
    const f = floorStats(a.floor);return [a.floor,n(f.regularHP),n(f.eliteHP),a.floor%5===0?n(f.bossHP):'—',n(f.regularATK),n(f.eliteATK),a.floor%5===0?n(f.bossATK):'—'];
  }));
  md += '\n\nBoss HP is fixed to these reference builds, never scaled to the gear currently equipped by a visitor. Single-squad focused contact times are 2 / 8 / 45 seconds before movement, retargeting, and commands. Multiple squads kill the same floor encounter faster.\n\n## Floor 50 mixed squad (Mythical 7-star weapons)\n\n';
  md += table(['Hero','Seed damage','Health','Normal hit','Tick interval (s)','DPS','Overdrive DPS while active'],mixed.map(h=>{
    const x = stats(h,5,50,7,7),q = stats(h,5,50,7,7,1,true);
    return [h.name,h.atk,n(x.hp),n(x.atk),n(x.tickInterval,2),n(x.dps),n(q.dps)];
  }));
  const sum = mixed.reduce((a,h)=>a+stats(h,5,50,7,7).dps,0);
  const low = mixed.reduce((a,h)=>a+stats(h,5,50,7,7,.9).dps,0);
  md += `\n\nMixed squad: **${n(sum)} DPS**, or **${n(.75*sum)} DPS at 75% uptime**. At minimum quality (0.90), 75% uptime still gives **${n(.75*low)} DPS**. Against floor 50 boss HP (${n(f50.bossHP)}), Mythical mixed-squad uninterrupted TTK is **${n(f50.bossHP/sum,2)} seconds**, or **${n(f50.bossHP/(.75*sum),2)} seconds at 75% uptime**, before Overdrive/exposure.\n\n`;
  md += '## Hero seed normalization (no weapon, level 1, q = 1)\n\n';
  md += table(['Hero','Native stars','1-star health seed','1-star damage seed','Native health','Native damage','Movement speed (studs/s)','Base attack speed (attacks/s)','Range metadata (studs)','Native labor/min','Preferred facility'],heroes.map(h=>{
    const x=stats(h,h.stars,1,0,1);return [h.name,h.stars,h.hp,h.atk,n(x.hp),n(x.atk),h.moveSpeed,n(1/h.interval,4),h.range,n(labor(h,h.stars,1),2),h.facility];
  }));
  md += '\n\n## Promotion continuity and unarmed Han\n\n';
  const milestones=[[1,1],[1,10],[2,10],[2,20],[3,20],[3,30],[4,30],[4,40],[5,40],[5,50]];
  md += table(['Stars','Level','Growth','Unarmed damage','Health','Labor/min (no synergy)'],milestones.map(([s,l])=>{
    const h=stats(heroes[0],s,l,0,1);return [s,l,n(growth(s,l),4),n(h.atk),n(h.hp),n(labor(heroes[0],s,l),2)];
  }));
  md += '\n\n## Weapon rarity and star constants\n\n';
  md += table(['Tier','Rarity','1-star inherent power','Attack speed bonus','Color','Stat reference scope'],rarities.map((r,i)=>[i+1,r[0],n(r[1]),n(r[2]*100,1)+'%',r[3],i<benchmarkRarityCount?'Within level-50 reference':'Above level-50 reference']));
  md += '\n\n'+table(['Weapon stars','Power multiplier'],weaponStars.map((v,i)=>[i+1,n(v,2)+'x']));
  md += '\n\nPower amplifies trained attack damage; it is not flat final damage. Only star promotion changes owned weapon power. Rarity is immutable. Weapon stars do not multiply speed, range, quality, labor, or HP. There is no weapon level, enhancement field, or rarity-refinement action. No named weapon bypasses the formula.\n';
  md += '\n## Weapon power by inherent rarity and promoted stars\n\n';
  md += table(['Inherent rarity',...weaponStars.map((_,i)=>(i+1)+'-star power'),'7-star damage multiplier'],rarities.map((r,i)=>[r[0]+(i>=benchmarkRarityCount?' (above reference)':''),...weaponStars.map((_,w)=>n(power(i+1,w+1))),n(1+power(i+1,7)/40,2)+'x']));
  md += '\n\nInherent rarity and its speed bonus stay fixed; progressive stars multiply power. Mythical is the level-50/floor-50 stat reference. Higher rarities are outside that required build; this calculator defines no drops, acquisition restrictions, rewards, or banner rules. There are no enhancement levels.\n';
  md += '\n## Weapon-only contribution example (5-star level-50 Han)\n\n';
  md += table(['Weapon','Power','Trained-damage multiplier','Hero damage / hit','Hero attack speed','Scheduled DPS'],[[1,1],[1,7],[6,1],[6,7],[7,1],[7,7]].map(([r,w])=>{const h=stats(heroes[0],5,50,r,w);return [rarities[r-1][0]+' '+w+'-star',n(power(r,w)),n(1+power(r,w)/40,2)+'x',n(h.atk),n(h.attackSpeed,4),n(h.dps)];}));
  md += '\n';
  const heads=['Floor','ReferenceSquadDPS','ReferenceHanHP','RegularHP','EliteHP','BossHP_OnlySpawnsEvery5Floors','RegularATK','EliteATK','BossATK_OnlySpawnsEvery5Floors'];
  const csv=[heads.join(',')];
  for(let f=1;f<=50;f++){
    const x=floorStats(f);csv.push([f,x.dps.toFixed(6),x.hp.toFixed(6),x.regularHP,x.eliteHP,f%5===0?x.bossHP:'',x.regularATK,x.eliteATK,f%5===0?x.bossATK:''].join(','));
  }
  return {'STAT_SCALING_TABLES.md':md,'FLOOR_SCALING.csv':csv.join('\n')+'\n'};
}

function validate() {
  assert.equal(power(7,7),112000);
  assert.deepEqual(weaponStars,[1,1.6,2.5,4,6.5,10,16]);
  assert.equal(stats(heroes[0],1,1,1,1).atk,60);
  assert.equal(stats(heroes[0],1,1,1,1).hp,300);
  assert.equal(stats(heroes[0],1,1,1,1).tickInterval,1);
  const mixed=heroes.filter(h=>['Han','Jenna','Aaron','Velkist','Eolka'].includes(h.name));
  const dps=mixed.reduce((a,h)=>a+stats(h,5,50,7,7,.9).dps,0);
  assert(dps*.75>=1e9,'Floor 50 must reach billions even at low quality and 75% uptime');
  assert(dps<1e10,'Keep the target in billions, not accidentally trillions');
  const attackSeconds=floorStats(50).bossHP/dps;
  const elapsedSeconds=attackSeconds/.75;
  const stamina=attackSeconds*1.5 + 5*Math.ceil(elapsedSeconds/20);
  assert(stamina<=100,'Rested low-quality reference attempt must fit the rough stamina budget');
  for(let s=1;s<5;s++) assert.equal(growth(s+1,10*s)/growth(s,10*s),3);
  let prev=0;
  for(let f=1;f<=50;f++){
    const x=floorStats(f);assert(x.dps>prev);prev=x.dps;
    for(const [key,value] of Object.entries(x)) assert(Number.isFinite(value)&&value>0,key);
    assert(x.regularHP<x.eliteHP&&x.eliteHP<x.bossHP);
    assert(x.bossHP<Number.MAX_SAFE_INTEGER);
    assert(Math.abs(x.bossHP/x.dps-45)<.01);
  }
  for(const h of heroes) for(let r=1;r<=16;r++) for(let w=1;w<=7;w++){
    const a=stats(h,5,50,r,w),b=stats(h,5,50,r,w,1,true);
    assert(a.atk>0&&a.hp>0&&a.tickInterval>=.2&&b.dps>=a.dps);
    assert(a.attackSpeed<=5&&b.attackSpeed<=5);
    assert.equal(a.moveSpeed,20);
    if(w<7) assert(stats(h,5,50,r,w+1).atk>a.atk);
    if(r<16) assert(stats(h,5,50,r+1,w).dps>=a.dps);
    assert.equal(a.hp,stats(h,5,50,0,1).hp);
  }
  for(const a of anchors) { assert(a.l<=a.s*10); assert(a.r<=benchmarkRarityCount); }
  assert.equal(anchors.at(-1).r,7);
}

if(require.main===module){
  validate();
  const generated=outputs();
  for(const [name,body] of Object.entries(generated)){
    const target=path.join(__dirname,name);
    if(process.argv.includes('--write'))fs.writeFileSync(target,body,'utf8');
    if(process.argv.includes('--check'))assert.equal(fs.readFileSync(target,'utf8'),body,`${name} is stale; run --write`);
  }
  console.log('PASS: 50-floor curve; low-quality 75%-uptime billion-DPS target; promotion continuity; 343 reference + 441 higher-rarity hero/weapon combinations; generated references.');
}
module.exports={benchmarkRarityCount,rarities,weaponStars,heroes,builds,growth,labor,power,stats,anchors,floorStats,outputs,table};
